const fs=require('fs'); const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8'));
const targets=findings.filter(x=>x.rule==='@performance/hp-arkui-remove-container-without-property');
const by=new Map(); for(const x of targets){if("'!by.has(x.relative_path))by.set(x.relative_path,[]);by.get(x.relative_path).push(x.line)}
function braceDelta(s){let n=0, q=null, esc=false, lineComment=false, block=false; for(let i=0;i<s.length;i++){let c=s[i],d=s[i+1]; if(lineComment)break; if(block){if(c==='"'*'&&d==='/'){block=false;i++} continue;} if(q){if(esc){esc=false;continue} if(c==='\\\\'){esc=true;continue} if(c===q)q=null;continue} if(c==='/'&&d==='/'){lineComment=true;break} if(c==='/'&&d==='*'){block=true;i++;continue} if(c==='\"'||c===\"'\"||c==='"'`'"'){q=c;continue} if(c==='{')n++; else if(c==='}')n--; } return n}
for(const [file,lines] of by){const src=fs.readFileSync(file,'utf8').split(/\\r?\\n/); console.log('--- '+file); for(const lineNo of [...new Set(lines)].sort((a,b)=>a-b)){let i=lineNo-1; let delta=braceDelta(src[i]); let j=i+1; while(delta>0&&j<src.length){delta+=braceDelta(src[j]);j++} console.log("'`${lineNo} -> ${j} | ${src[i].trim()} | CLOSE ${src[j-1]?.trim()}`); for(let k=i;k<Math.min(j,i+4);k++)console.log('"'  '+(k+1)+' '+src[k].trim());}}
