/usr/bin/bash -lc "node <<'NODE'
const fs=require('fs'); const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8'));
const targets=findings.filter(x=>x.rule==='@performance/hp-arkui-remove-container-without-property');
const by=new Map(); for(const x of targets){if("'!by.has(x.relative_path))by.set(x.relative_path,[]);by.get(x.relative_path).push(x.line)}
function braceDelta(s){let n=0,q=null,esc=false,line=false,block=false;for(let i=0;i<s.length;i++){let c=s[i],d=s[i+1];if(line)break;if(block){if(c==='"'*'&&d==='/'){block=false;i++}continue}if(q){if(esc){esc=false;continue}if(c==='\\\\'){esc=true;continue}if(c===q)q=null;continue}if(c==='/'&&d==='/'){line=true;break}if(c==='/'&&d==='*'){block=true;i++;continue}if(c==='\"'||c===\"'\"||c==='"'`'"'){q=c;continue}if(c==='{')n++;else if(c==='}')n--}return n}
function q(s){return s.replace(/\\\\/g,'\\\\\\\\').replace(/\\"'$/g,'"'\\\\"'$'"').replace(/"'`/g,'"'\\\\"'`'"')}
let patch='*** Begin Patch\\n';
for(const [file,lines] of by){const src=fs.readFileSync(file,'utf8').split(/\\r?\\n/); const dels=[];
 for(const lineNo of [...new Set(lines)].sort((a,b)=>a-b)){let i=lineNo-1,d=braceDelta(src[i]),j=i+1;while(d>0&&j<src.length){d+=braceDelta(src[j]);j++} if(d"'!==0) throw new Error(`${file}:${lineNo} unmatched`); dels.push(i,j-1)}
 patch+=`*** Update File: ${file}'"\\n"'`;
 for(const i of dels){
   const prev=i>0?src[i-1]:null, next=i+1<src.length?src[i+1]:null;
   patch+='"'@@\\n'; if(prev"'!==null) patch+='"' '+prev+'\\n'; patch+='-'+src[i]+'\\n'; if(next"'!==null) patch+='"' '+next+'\\n';
 }
}
patch+='*** End Patch\\n'; process.stdout.write(patch);
NODE"

/usr/bin/bash -lc "node <<'NODE'
const fs=require('fs'),os=require('os'),cp=require('child_process'),path=require('path');
const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8'));
const by=new Map(); for(const x of findings.filter(x=>x.rule==='@performance/hp-arkui-remove-container-without-property')){if("'!by.has(x.relative_path))by.set(x.relative_path,[]);by.get(x.relative_path).push(x.line)}
function delta(s){let n=0,q=null,e=false,l=false,b=false;for(let i=0;i<s.length;i++){let c=s[i],d=s[i+1];if(l)break;if(b){if(c==='"'*'&&d==='/'){b=false;i++}continue}if(q){if(e){e=false;continue}if(c==='\\\\'){e=true;continue}if(c===q)q=null;continue}if(c==='/'&&d==='/'){l=true;break}if(c==='/'&&d==='*'){b=true;i++;continue}if(c==='\"'||c===\"'\"||c==='"'`'"'){q=c;continue}if(c==='{')n++;else if(c==='}')n--}return n}
let out='*** Begin Patch\\n'; const tmp=[];
for(const [file,lines] of by){const eol=fs.readFileSync(file,'utf8').includes('\\r\\n')?'\\r\\n':'\\n'; const src=fs.readFileSync(file,'utf8').split(/\\r?\\n/); const remove=new Set();
 for(const ln of [...new Set(lines)]){let i=ln-1,d=delta(src[i]),j=i+1;while(d>0&&j<src.length){d+=delta(src[j]);j++}if(d"'!==0)throw Error(`${file}:${ln}`);remove.add(i);remove.add(j-1)}
 const newer=src.filter((_,i)=>!remove.has(i)).join(eol); const t=path.join(os.tmpdir(),'"'haprepair-'+process.pid+'-'+Math.random().toString(16).slice(2));fs.writeFileSync(t,newer);tmp.push(t);
 let diff='';try{diff=cp.execFileSync('diff',['-u','--label',file,'--label',file,file,t],{encoding:'utf8'});}catch(err){if(err.status"'!==1)throw err;diff=err.stdout;}
 const linesDiff=diff.split(/'"\\r?\\n/); out+="'`*** Update File: ${file}'"\\n"'`+linesDiff.slice(2).join('"'\\n'); if("'!out.endsWith('"'\\n'))out+='\\n';
}
out+='*** End Patch\\n'; for(const t of tmp)try{fs.unlinkSync(t)}catch(e){} process.stdout.write(out);
NODE"

/usr/bin/bash -lc "node <<'NODE'
const fs=require('fs');
const file=\"entry/src/main/ets/pages/ArkUI/AccessBilityHoverTransparent.ets\";
const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8')).filter(x=>x.rule==='@performance/hp-arkui-remove-container-without-property'&&x.relative_path===file);
const eol=fs.readFileSync(file,'utf8').includes('\\r\\n')?'\\r\\n':'\\n';
const lines=fs.readFileSync(file,'utf8').split(/\\r?\\n/);
function delta(s){let n=0,q=null,e=false,l=false,b=false;for(let i=0;i<s.length;i++){let c=s[i],d=s[i+1];if(l)break;if(b){if(c==='*'&&d==='/'){b=false;i++}continue}if(q){if(e){e=false;continue}if(c==='\\\\'){e=true;continue}if(c===q)q=null;continue}if(c==='/'&&d==='/'){l=true;break}if(c==='/'&&d==='*'){b=true;i++;continue}if(c==='\"'||c===\"'\"||c==='\\"'`'"'){q=c;continue}if(c==='{')n++;else if(c==='}')n--}return n}
const remove=new Set();
for(const x of findings){let i=x.line-1;if(remove.has(i))continue;let d=delta(lines[i]),j=i+1;while(d>0&&j<lines.length){d+=delta(lines[j]);j++}if(d"'!==0)throw Error(file+'"':'+x.line+' unmatched '+d);remove.add(i);remove.add(j-1)}
let p='*** Begin Patch\\n*** Update File: '+file+'\\n@@\\n';
for(let i=0;i<lines.length;i++)p+=(remove.has(i)?'-':' ')+lines[i]+'\\n';
p+='*** End Patch\\n';process.stdout.write(p);
