  for(let j=i;j<=states.length;j++){
    const skip=dp[i][j-1];
    const use=dp[i-1][j-1]+Math.abs(states[j-1]-targets[i-1]);
    if(use<=skip){dp[i][j]=use;take[i][j]=true}else dp[i][j]=skip;
  }
}
