const file=\"entry/src/main/ets/pages/Screen/Screen_index.ets\";
const findings=JSON.parse(fs.readFileSync('.exp_agent/findings_round_01.json','utf8')).filter(x=>x.relative_path===file&&/state-var/.test(x.rule));
const targets=[...new Set(findings.map(x=>x.line))].sort((a,b)=>a-b);
const lines=fs.readFileSync(file,'utf8').split(/\\r?\\n/);
const states=[]; for(let i=0;i<lines.length;i++) if(/"'^'"\\s*@State\\b/.test(lines[i])) states.push(i+1);
if(targets.length===0){process.exit(0)}
if(states.length<targets.length) throw Error(file+': target '+targets.length+' states '+states.length);
// Order-preserving minimum-distance mapping from frozen declaration lines to current lines after earlier edits.
const dp=Array.from({length:targets.length+1},()=>Array(states.length+1).fill(Infinity));
const take=Array.from({length:targets.length+1},()=>Array(states.length+1).fill(false));
for(let j=0;j<=states.length;j++) dp[0][j]=0;
for(let i=1;i<=targets.length;i++){
  for(let j=i;j<=states.length;j++){
    const skip=dp[i][j-1];
    const use=dp[i-1][j-1]+Math.abs(states[j-1]-targets[i-1]);
    if(use<=skip){dp[i][j]=use;take[i][j]=true}else dp[i][j]=skip;
  }
}
let i=targets.length,j=states.length,mapped=[];
while(i>0){if(take[i][j]){mapped.push(states[j-1]);i--;j--}else j--}
mapped.reverse();
const remove=new Set(mapped.map(x=>x-1));
let p='*** Begin Patch\\n*** Update File: '+file+'\\n@@\\n';
for(let k=0;k<lines.length;k++){let line=lines[k];if(remove.has(k))line=line.replace('@State','');p+=(remove.has(k)?'-':' ')+lines[k]+'\\n'+(remove.has(k)?'+'+line+'\\n':'')}
p+='*** End Patch\\n';process.stdout.write(p);
NODE"

